<script setup lang="ts">
import{computed,onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{AlertTriangle,ArrowLeft,Check,Copy,Edit3,FolderTree,RefreshCw,Workflow}from'lucide-vue-next';import{api}from'../api';import{copyText}from'../utils';import{useAppStore}from'../stores/app';import type{Group,NodeSnapshot,OutputStatus,RefreshRun}from'../types';import StatusTag from'../components/StatusTag.vue';
const route=useRoute(),router=useRouter(),app=useAppStore(),id=Number(route.params.id),group=ref<(Group&{recent_runs?:RefreshRun[]})|null>(null),nodes=ref<NodeSnapshot[]>([]),outputs=ref<OutputStatus[]>([]),runs=ref<RefreshRun[]>([]),tab=ref('overview'),loading=ref(false),tabLoading=ref(false),refreshing=ref(false),nodeBusy=ref(''),ordering=ref(false),orderSaving=ref(false);const loaded=new Set<string>();const enabledUpstreams=computed(()=>group.value?.upstreams.filter(x=>x.enabled)||[]);const pendingNodes=computed(()=>nodes.value.filter(x=>x.confirmation_status!=='confirmed'));const dt=(v?:string)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';const duration=(v?:number)=>v==null?'—':v<1000?`${v} ms`:`${(v/1000).toFixed(1)} s`;const size=(v:number)=>v>1048576?`${(v/1048576).toFixed(1)} MB`:v>1024?`${(v/1024).toFixed(1)} KB`:`${v} B`;
async function loadGroup(initial=false){if(initial)loading.value=true;try{group.value=await api(`/api/subscriptions/${id}`)}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}
async function loadTab(name:string,force=false){if(name==='overview'||loaded.has(name)&&!force)return;tabLoading.value=true;try{if(name==='nodes')nodes.value=(await api<any>(`/api/subscriptions/${id}/nodes`)).nodes;if(name==='outputs')outputs.value=(await api<any>(`/api/subscriptions/${id}/outputs/status`)).outputs;if(name==='runs')runs.value=(await api<any>(`/api/subscriptions/${id}/runs?page_size=30`)).items;loaded.add(name)}catch(e:any){ElMessage.error(e.message)}finally{tabLoading.value=false}}
async function refresh(){if(refreshing.value)return;refreshing.value=true;try{await api(`/api/subscriptions/${id}/refresh`,{method:'POST'});ElMessage.success('刷新任务已完成');loaded.clear();await loadGroup();await loadTab(tab.value,true)}catch(e:any){ElMessage.error(e.message)}finally{refreshing.value=false}}
async function updateNode(row:NodeSnapshot,alias:string|null){nodeBusy.value=row.node_key;try{const result:any=await api(`/api/subscriptions/${id}/nodes/${row.node_key}`,{method:'PUT',body:JSON.stringify({alias,confirm:true})});nodes.value=result.nodes.nodes;loaded.add('nodes');await loadGroup();ElMessage.success(alias?'节点别名已保存':'节点设置已更新')}catch(e:any){ElMessage.error(e.message)}finally{nodeBusy.value=''}}
async function editAlias(row:NodeSnapshot){try{const{value}=await ElMessageBox.prompt('固定名称支持竖线、国旗和常见符号；流量与天数仍会动态追加。','设置节点别名',{inputValue:row.alias||'',inputPlaceholder:'例如：07|🇭🇰|香港住宅',inputValidator:(v:string)=>v.length<=80&&!/[\r\n]/.test(v)||'最多 80 字，且不能包含换行',confirmButtonText:'保存',cancelButtonText:'取消'});await updateNode(row,value.trim()||null)}catch(e:any){if(e!=='cancel'&&e!=='close')throw e}}
function moveNode(index:number,delta:number){const next=index+delta;if(next<0||next>=nodes.value.length)return;const copy=nodes.value.slice();const item=copy.splice(index,1)[0];copy.splice(next,0,item);nodes.value=copy}
async function saveNodeOrder(){if(!nodes.value.length)return;orderSaving.value=true;try{const result:any=await api(`/api/subscriptions/${id}/nodes/order`,{method:'PUT',body:JSON.stringify({node_keys:nodes.value.map(x=>x.node_key)})});nodes.value=result.nodes.nodes;ordering.value=false;loaded.add('nodes');await loadGroup();ElMessage.success('节点顺序已保存，下游订阅已更新')}catch(e:any){ElMessage.error(e.message)}finally{orderSaving.value=false}}
async function confirmAll(){nodeBusy.value='all';try{const result:any=await api(`/api/subscriptions/${id}/nodes/confirm`,{method:'POST',body:JSON.stringify({node_keys:null})});nodes.value=result.nodes.nodes;loaded.add('nodes');await loadGroup();ElMessage.success(`已确认 ${result.confirmed} 个节点`)}catch(e:any){ElMessage.error(e.message)}finally{nodeBusy.value=''}}
async function copy(v?:string){if(!v)return;await copyText(v);ElMessage.success('订阅地址已复制')}
watch(tab,name=>loadTab(name));onMounted(async()=>{await Promise.all([loadGroup(true),app.settings?Promise.resolve():app.bootstrap()])})
</script>
<template><section class="page group-detail-page"><header class="page-head"><div><button class="back" @click="router.push('/groups')"><ArrowLeft/></button><p class="eyebrow">GROUP OPERATIONS</p><h1>{{group?.name||'订阅组详情'}}</h1><p>{{group?.note||'查看来源、节点、输出和运行记录。'}}</p></div><div class="head-actions"><el-button @click="router.push(`/groups/${id}/categories`)"><FolderTree/>分类管理</el-button><el-button @click="router.push(`/groups/${id}/edit`)"><Edit3/>编辑配置</el-button><el-button type="primary" :loading="refreshing" @click="refresh"><RefreshCw/>立即刷新</el-button></div></header>
<el-skeleton v-if="loading&&!group" :rows="8" animated/><template v-else-if="group"><div class="detail-summary"><StatusTag :status="group.last_refresh_status"/><span>缓存 <b>{{group.cache_state==='fresh'?'新鲜':group.cache_state==='stale'?'旧缓存':'暂无'}}</b></span><span>最近成功 <b>{{dt(group.last_success_at)}}</b></span><span>下次刷新 <b>{{dt(group.next_refresh_at)}}</b></span><span v-if="group.pending_node_count" class="pending-summary"><AlertTriangle/>{{group.pending_node_count}} 个节点待确认</span></div>
<el-tabs v-model="tab" class="detail-tabs"><el-tab-pane label="概览" name="overview"><div class="stats"><div class="stat"><div><b>{{group.node_count}}</b><span>有效节点</span></div></div><div class="stat"><div><b>{{group.filtered_count}}</b><span>过滤/去重</span></div></div><div class="stat"><div><b>{{enabledUpstreams.filter(x=>x.last_status==='ok').length}} / {{enabledUpstreams.length}}</b><span>健康上游</span></div></div><div class="stat"><div><b>{{duration(group.last_duration_ms)}}</b><span>刷新耗时</span></div></div></div><el-alert v-if="group.last_error" type="warning" title="最近异常" :description="group.last_error" :closable="false" show-icon/><div v-if="group.pending_node_count" class="pending-banner panel"><AlertTriangle/><div><b>{{group.pending_node_count}} 个节点需要确认</b><span>新增节点或上游固定名称发生变化，下游暂时带有 ⚠️ 标记。</span></div><el-button type="warning" plain @click="tab='nodes'">前往处理</el-button></div><div v-else class="healthy-banner panel"><Check/><div><b>全部正常</b><span>没有异常状态或待确认节点。</span></div></div>
<div class="detail-overview-grid"><section class="panel overview-card"><header><div><h3>上游健康</h3><span>最近一次拉取结果</span></div><button @click="tab='upstreams'">查看全部</button></header><div class="overview-rows"><div v-for="u in enabledUpstreams.slice(0,5)" :key="u.id"><StatusTag :status="u.last_status"/><span><b>{{u.name}}</b><small>{{u.source_format||'未知格式'}} · {{u.node_count||0}} 节点</small></span><time>{{duration(u.last_duration_ms)}}</time></div></div></section><section class="panel overview-card"><header><div><h3>输出客户端</h3><span>{{group.outputs.filter(x=>x.enabled).length}} 个固定地址</span></div><button @click="tab='outputs'">查看地址</button></header><div class="overview-rows"><div v-for="o in group.outputs.filter(x=>x.enabled).slice(0,5)" :key="o.id"><Workflow/><span><b>{{o.name}}</b><small>{{app.types[o.client_type]?.label||o.client_type}}</small></span><i class="healthy-dot">可用</i></div></div></section></div>
<section class="panel overview-card overview-runs"><header><div><h3>最近刷新</h3><span>最近 5 次真实刷新任务</span></div><button @click="tab='runs'">完整记录</button></header><div v-if="group.recent_runs?.length" class="run-strip"><div v-for="r in group.recent_runs" :key="r.id"><StatusTag :status="r.status"/><span>{{r.trigger==='scheduler'?'定时':r.trigger==='manual'?'手动':'公共请求'}}</span><b>{{r.node_count}} 节点</b><span>{{duration(r.duration_ms)}}</span><time>{{dt(r.finished_at)}}</time></div></div><div v-else class="mini-empty">暂无刷新记录</div></section><div class="panel overview-info"><div><span>自动刷新周期</span><b>{{group.interval_minutes}} 分钟</b></div><div><span>刷新次数</span><b>{{group.refresh_count}}</b></div><div><span>改名模式</span><b>{{group.rename_mode==='smart'?'智能规则':'原样透传'}}</b></div><div><span>配置状态</span><b>{{group.enabled?'已启用':'已停用'}}</b></div></div></el-tab-pane>
<el-tab-pane label="上游" name="upstreams"><div class="panel"><el-table :data="group.upstreams"><el-table-column prop="name" label="上游" min-width="170"/><el-table-column label="改名规则" width="120"><template #default="{row}">{{row.rename_policy==='inherit'?'继承组规则':row.rename_policy==='smart'?'独立规则':'原样透传'}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><StatusTag :status="row.last_status"/></template></el-table-column><el-table-column prop="source_format" label="格式" width="120"/><el-table-column prop="last_http_status" label="HTTP" width="80"/><el-table-column prop="node_count" label="节点" width="80"/><el-table-column label="大小" width="100"><template #default="{row}">{{size(row.last_bytes||0)}}</template></el-table-column><el-table-column label="耗时" width="100"><template #default="{row}">{{duration(row.last_duration_ms)}}</template></el-table-column><el-table-column label="最近成功" min-width="175"><template #default="{row}">{{dt(row.last_success_at)}}</template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane :label="`节点${group.pending_node_count?` (${group.pending_node_count})`:''}`" name="nodes"><div v-loading="tabLoading" class="panel node-panel"><div class="section-toolbar"><span>最后有效的脱敏节点快照，共 {{nodes.length}} 条</span><div class="node-order-actions"><el-button v-if="nodes.length" plain @click="ordering=!ordering">{{ordering?'完成调整':'调整顺序'}}</el-button><el-button v-if="ordering" type="primary" :loading="orderSaving" @click="saveNodeOrder">保存顺序</el-button><el-button v-if="pendingNodes.length" type="warning" plain :loading="nodeBusy==='all'" @click="confirmAll"><Check/>全部确认</el-button></div></div><el-table :data="nodes" empty-text="刷新成功后将在此生成脱敏节点快照"><el-table-column v-if="ordering" label="调整" width="116"><template #default="{row,$index}"><el-button link :disabled="$index===0" @click="moveNode($index,-1)">上移</el-button><el-button link :disabled="$index===nodes.length-1" @click="moveNode($index,1)">下移</el-button></template></el-table-column><el-table-column label="#" width="52"><template #default="{ $index }">{{ $index+1 }}</template></el-table-column><el-table-column prop="source_name" label="来源" width="125" show-overflow-tooltip/><el-table-column prop="original_name" label="原名" min-width="190" show-overflow-tooltip/><el-table-column prop="rule_name" label="规则结果" min-width="180" show-overflow-tooltip/><el-table-column prop="alias" label="自定义名称" min-width="150"><template #default="{row}">{{row.alias||'—'}}</template></el-table-column><el-table-column prop="final_name" label="最终下游名称" min-width="200" show-overflow-tooltip/><el-table-column label="测活" width="110"><template #default="{row}"><span class="node-state" :class="row.health_status">{{row.health_status==='healthy'?(row.connectivity_latency_ms?row.connectivity_latency_ms+' ms':'正常'):row.health_status==='unavailable'?'不可用':row.health_status==='google_blocked'?'Google 不通':'未测试'}}</span></template></el-table-column><el-table-column label="状态" width="118"><template #default="{row}"><span class="node-state" :class="row.confirmation_status">{{row.confirmation_status==='confirmed'?'已确认':row.confirmation_status==='pending_new'?'新增待确认':'名称变化'}}</span></template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link type="primary" :loading="nodeBusy===row.node_key" @click="editAlias(row)">改名</el-button><el-button v-if="row.confirmation_status!=='confirmed'" link type="warning" @click="updateNode(row,row.alias||null)">确认</el-button><el-button v-if="row.alias" link @click="updateNode(row,null)">清除</el-button></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="输出" name="outputs"><div v-loading="tabLoading" class="output-status-grid"><article v-for="o in outputs" :key="o.id" class="panel output-status-card"><header><div><b>{{o.name}}</b><span>{{app.types[o.client_type]?.label||o.client_type}}</span></div><span class="cache" :class="o.status==='ready'?'fresh':''">{{o.status==='ready'?'已生成':'暂无缓存'}}</span></header><div class="output-meta"><span>更新时间<b>{{dt(o.updated_at)}}</b></span><span>大小<b>{{size(o.bytes)}}</b></span><span>渲染器<b>{{o.renderer||'—'}}</b></span><span>跳过节点<b>{{o.skipped_nodes}}</b></span></div><el-button :disabled="!o.url" @click="copy(o.url)"><Copy/>复制固定地址</el-button></article></div></el-tab-pane>
<el-tab-pane label="刷新记录" name="runs"><div v-loading="tabLoading" class="panel"><el-table :data="runs" empty-text="暂无刷新记录"><el-table-column label="状态" width="110"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column label="来源" width="100"><template #default="{row}">{{row.trigger==='manual'?'手动':row.trigger==='scheduler'?'定时':'公共请求'}}</template></el-table-column><el-table-column label="上游" width="90"><template #default="{row}">{{row.upstream_success}}/{{row.upstream_total}}</template></el-table-column><el-table-column label="输出" width="90"><template #default="{row}">{{row.output_success}}/{{row.output_total}}</template></el-table-column><el-table-column prop="node_count" label="节点" width="80"/><el-table-column label="耗时" width="100"><template #default="{row}">{{duration(row.duration_ms)}}</template></el-table-column><el-table-column label="时间" min-width="170"><template #default="{row}">{{dt(row.finished_at)}}</template></el-table-column></el-table></div></el-tab-pane><el-tab-pane label="配置" name="config"><div class="panel config-jump"><Edit3/><h3>配置在独立页面中编辑</h3><p>避免运维数据和敏感上游地址混在同一个视图。</p><el-button type="primary" @click="router.push(`/groups/${id}/edit`)">进入配置编辑</el-button></div></el-tab-pane></el-tabs></template></section></template>
